import{z as n,x as B,o as t,c as d,q as s,j as l,D as e,d as r,s as i,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"上下文无关文法","description":"","frontmatter":{"title":"上下文无关文法","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cfg-grammar.md","filePath":"cs/cfg-grammar.md","lastUpdated":1791413859000}'),C={name:"cs/cfg-grammar.md"};function p(m,a,F,c,h,f){const o=B("Mermaid");return t(),d("div",null,[a[2]||(a[2]=s('<h1 id="上下文无关文法" tabindex="-1">上下文无关文法 <a class="header-anchor" href="#上下文无关文法" aria-label="Permalink to &quot;上下文无关文法&quot;">​</a></h1><div class="epigraph"><p>短语结构用产生式 $A\\to\\alpha$ 递归展开；推导树给出嵌套，正则做不到的括号匹配在这里落地。</p><footer>—— 据 Chomsky, On Certain Formal Properties of Grammars, 1959；龙书第 4 章整理</footer></div><p>上一课<a href="/cs/thompson-nfa">Thompson 构造</a>交出记号流。本课不重写 DFA。缺口是：表达式、语句、声明的<strong>嵌套</strong>。正则无法强制括号配对。上下文无关文法（CFG）以非终结符加产生式描述记号上的语言。本课只钉文法、推导、二义；怎么造分析器是后课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>记号流是否为一份合法程序，不能只靠有限记忆。CFG：\\(G=(V,\\Sigma,P,S)\\)，\\(\\Sigma\\) 是记号种别，\\(P\\) 为 \\(A\\to\\alpha\\)。<span class="marginnote">「产生式 \\(A\\to\\alpha\\)」读作「A 可以改写成 α」：大写字母是可以继续展开的占位符（非终结符），展开结果里混着占位符与真实单词（终结符）。从开始符号出发不停改写，直到剩下全是真实单词——所有能这样得到的句子，就是这门文法定义的语言。</span>最左推导对应一种分析次序。语言 \\(L(G)\\) 是 \\(S\\) 能推出的终结串。缺口是这份定义，不是 Yacc 的语法。</p><p>二义：同一串两棵不同的推导树。悬空 else、运算符结合性必须用改写文法或后课的优先级声明消除，否则语义没有唯一 AST。</p><h3 id="cfg-不是「有上下文」" tabindex="-1">CFG 不是「有上下文」 <a class="header-anchor" href="#cfg-不是「有上下文」" aria-label="Permalink to &quot;CFG 不是「有上下文」&quot;">​</a></h3><p>名字易误导：产生式左端是单个非终结符，<strong>不看</strong>周围上下文。上下文有关文法是另一族，编译前端不用。类型规则「此处该是 int」是语义，不是 CFG 的上下文。<span class="marginnote">常见误区：把「上下文无关」理解成「没有上下文」。它真正说的是「展开规则只看左边是哪个符号，不看它周围站着谁」——规则 \\(E \\to E+E\\) 在任何位置都照用不误。而「变量先声明再用」这类要看前后文的约束属于语义层，本就另案处理。</span></p><p><span class="marginnote">Chomsky 层级把正则放在 CFG 之下：每个正则语言上下文无关。龙书第 4 章用表达式文法当第一份例子。本课记号已由词法切好，\\(\\Sigma\\) 不是字符。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写表达式与语句的产生式。给出最左推导与一棵树。指出二义并改写成强制结合（\\(E\\to E+T\\mid T\\)）。ε 产生式允许可选结构。开始符号对应「编译单元」。</p>',11)),(t(),l(A,null,{default:e(()=>[i(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%BC%80%E5%A7%8B%E7%AC%A6%E5%8F%B7%22%5D%20--%3E%20P%5B%22%E4%BA%A7%E7%94%9F%E5%BC%8F%E5%B1%95%E5%BC%80%22%5D%0A%20%20P%20--%3E%20T%5B%22%E6%8E%A8%E5%AF%BC%E6%A0%91%22%5D%0A%20%20T%20--%3E%20AMB%5B%22%E6%98%AF%E5%90%A6%E4%BA%8C%E4%B9%89%EF%BC%9F%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("a",{href:"/cs/tree-as-acyclic"},"树"),r("已定义；推导树是有序树，叶为记号。后课 AST 丢掉纯语法糖节点。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"CFG 的分析问题：给定 \\(G\\) 与记号串，是否 \\(w\\in L(G)\\) 并可建树。一般 CFG 可用 CYK 等动态规划，多项式但慢；程序语言用受限族（LL、LR）线性。本课不写 CYK。左递归对后课递归下降有害，点名留给那一课消除。",-1)),(t(),l(A,null,{default:e(()=>[i(o,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E8%BE%93%E5%85%A5%EF%BC%9A(%20(%20id%20)%20)%22%5D%20--%3E%20CFG%5B%22CFG%EF%BC%9AE%20%E2%87%92%20(%20E%20)%20%E9%80%92%E5%BD%92%E5%B1%95%E5%BC%80%22%5D%0A%20%20CFG%20--%3E%20D1%5B%22%E7%AC%AC%201%20%E5%B1%82%EF%BC%9A%E5%A4%96%E5%B1%82%E6%8B%AC%E5%8F%B7%E5%8D%A0%E4%BD%8F%22%5D%0A%20%20D1%20--%3E%20D2%5B%22%E7%AC%AC%202%20%E5%B1%82%EF%BC%9A%E5%86%85%E5%B1%82%E6%8B%AC%E5%8F%B7%E5%8D%A0%E4%BD%8F%22%5D%0A%20%20D2%20--%3E%20D3%5B%22%E7%AC%AC%203%20%E5%B1%82%EF%BC%9Aid%22%5D%0A%20%20D3%20--%3E%20ACC%5B%22%E5%B1%82%E5%B1%82%E9%97%AD%E5%90%88%EF%BC%8C%E6%8E%A5%E5%8F%97%22%5D%0A%20%20IN%20--%3E%20RE%5B%22%E6%AD%A3%E5%88%99%EF%BC%9A%E6%9C%89%E9%99%90%E4%B8%AA%E7%8A%B6%E6%80%81%22%5D%0A%20%20RE%20--%3E%20LIM%5B%22%E7%8A%B6%E6%80%81%E6%95%B0%E5%9B%BA%E5%AE%9A%EF%BC%8C%E6%8B%AC%E5%8F%B7%E6%B7%B1%E5%BA%A6%E6%97%A0%E9%99%90%22%5D%0A%20%20LIM%20--%3E%20REJ%5B%22%E6%B7%B1%E5%BA%A6%E8%B6%85%E8%BF%87%E7%8A%B6%E6%80%81%E6%95%B0%E5%B0%B1%E6%95%B0%E4%B8%A2%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">这张图回答「括号配对为什么卡死正则」：正则像只有固定几个口袋的口袋阵，括号深度无限，口袋总有数丢的一层；CFG 的递归展开像俄罗斯套娃，拆开一个非终结符，里面还可以再套一个，深度不加记忆。这是「正则 ⊂ 上下文无关」最直观的试金石。</span></p><p>正则词法仍负责标识符拼写；CFG 只看见 <code>id</code> 种别。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写递归下降代码，不算 FIRST/FOLLOW，不移进归约。语义动作不进产生式（那是语法制导，AST 课才挂）。也不用 CFG 描述空白——空白已在词法消失。</p><p>后课默认：程序结构是某份（希望无二义的）CFG。下一课先消二义与左递归，递归下降随后把最左推导写成函数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CFG 用单非终结符产生式描述嵌套；推导树是结构。</li><li>二义必须消；正则只管词法。</li><li>分析算法分家：本课只给语言。</li><li>出处：Chomsky, 1959；Aho et al., 龙书第 4 章。</li></ul>',7))])}const u=n(C,[["render",p]]);export{g as __pageData,u as default};
